<?php if($problemRow instanceof \stdClass){$problemRow=(array)$problemRow;}$problemTags=$problemRow['tags']??[];$primaryTag=$problemRow['tag_id']??($problemTags[0]['id']??''); ?>
<fieldset class="problem-row" data-problem-row><legend>مسئلهٔ تجربه</legend><input data-problem-field="id" name="problems[<?= $problemIndex ?>][id]" type="hidden" value="<?= $this->h($problemRow['id']??'') ?>">
<label>عنوان مشخص مسئله<input data-problem-field="title" name="problems[<?= $problemIndex ?>][title]" maxlength="300" value="<?= $this->h($problemRow['title']??'') ?>" placeholder="مثلاً تأمین بودجهٔ رویداد هنری"></label>
<label>شرح مسئله<textarea data-problem-field="description" name="problems[<?= $problemIndex ?>][description]" rows="3" maxlength="3000"><?= $this->h($problemRow['description']??'') ?></textarea></label>
<label>برچسب اصلی مسئله<select data-problem-field="tag_id" name="problems[<?= $problemIndex ?>][tag_id]"><option value="">انتخاب برچسب</option><?php foreach($terms as $tag):if($tag['kind']!=='issue'||(!$tag['active']&&$primaryTag!==$tag['id'])){continue;} ?><option value="<?= $this->h($tag['id']) ?>" <?= $primaryTag===$tag['id']?'selected':'' ?>><?= $this->h($tag['title']) ?><?= $tag['active']?'':' · غیرفعال، سابقهٔ قبلی' ?></option><?php endforeach; ?></select></label>
<?php if(count($problemTags)>1): ?><p class="small muted">برچسب‌های ثانویهٔ قبلی حفظ می‌شوند: <?= $this->h(implode('، ',array_column(array_slice($problemTags,1),'title'))) ?></p><?php endif; ?>
<button type="button" class="secondary" data-remove-problem>حذف این مسئله از پیش‌نویس جدید</button></fieldset>
